using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class BNInspect {
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 required");string h=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B2_DomeNetwork/"));var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();File.WriteAllText(h+"before.json",JsonConvert.SerializeObject(all.Select(t=>new{id=GlobalObjectId.GetGlobalObjectIdSlow(t).ToString(),t.name,position=new[]{t.position.x,t.position.y,t.position.z},active=t.gameObject.activeSelf}),Formatting.Indented));var root=s.GetRootGameObjects().Single(g=>g.name=="B2_C02_CoolingSector");var detail=root.GetComponentsInChildren<Transform>(true).Where(t=>t.name.Contains("Guard")||t.name.Contains("Collision")||t.name.Contains("Grating")).Select(t=>new{t.name,parent=t.parent?.name,asset=t.GetComponent<MeshFilter>()?AssetDatabase.GetAssetPath(t.GetComponent<MeshFilter>().sharedMesh):"",position=t.localPosition.ToString(),colliders=t.GetComponents<Collider>().Select(c=>new{type=c.GetType().Name,center=c.bounds.center.ToString(),size=c.bounds.size.ToString()}).ToArray()}).ToArray();File.WriteAllText(h+"c02.json",JsonConvert.SerializeObject(detail,Formatting.Indented));return new{objects=all.Length,c02=detail};}
}
